// OLED
// -----------------------------
#define OLED_SDA 5
#define OLED_SCL 6
#define OLED_WIDTH 72
#define OLED_HEIGHT 40
#define FRAME_SIZE 360

U8G2_SSD1306_72X40_ER_F_HW_I2C oled(
  U8G2_R0,
  U8X8_PIN_NONE,
  OLED_SCL,
  OLED_SDA
);

