// -----------------------------
// Storage/config
// -----------------------------
Preferences prefs;

static const uint8_t MAX_FRAMES = 30;
uint8_t frameBuffer[FRAME_SIZE];

uint8_t frameCount = 0;
uint8_t currentFrame = 0;
uint32_t slideshowInterval = 1000;
bool slideshowEnabled = false;
uint8_t oledBrightness = 255;

uint32_t lastFrameTime = 0;

// Upload state
size_t uploadBytes = 0;
int uploadTarget = -1;
bool uploadValid = false;

// -----------------------------
// File helpers
// -----------------------------
String framePath(uint8_t index) {
  char p[24];
  snprintf(p, sizeof(p), "/f%02u.bin", index);
  return String(p);
}

bool saveFrame(uint8_t index, const uint8_t* data) {
  if (index >= MAX_FRAMES) return false;

  File f = LittleFS.open(framePath(index), "w");
  if (!f) return false;

  size_t n = f.write(data, FRAME_SIZE);
  f.close();

  return n == FRAME_SIZE;
}

bool loadFrame(uint8_t index) {
  if (index >= frameCount) return false;

  File f = LittleFS.open(framePath(index), "r");
  if (!f || f.size() != FRAME_SIZE) {
    if (f) f.close();
    return false;
  }

  size_t n = f.read(frameBuffer, FRAME_SIZE);
  f.close();

  if (n != FRAME_SIZE) return false;

  currentFrame = index;

  oled.clearBuffer();
  oled.drawXBMP(0, 0, OLED_WIDTH, OLED_HEIGHT, frameBuffer);
  oled.sendBuffer();

  return true;
}

void clearDisplayOnly() {
  memset(frameBuffer, 0, FRAME_SIZE);
  oled.clearBuffer();
  oled.sendBuffer();
}

void clearAllFrames() {
  for (uint8_t i = 0; i < MAX_FRAMES; ++i) {
    String p = framePath(i);
    if (LittleFS.exists(p)) LittleFS.remove(p);
  }

  frameCount = 0;
  currentFrame = 0;
  slideshowEnabled = false;

  prefs.putUChar("frames", frameCount);
  prefs.putBool("slide", slideshowEnabled);

  clearDisplayOnly();
}

void saveConfig() {
  prefs.putUChar("frames", frameCount);
  prefs.putUInt("interval", slideshowInterval);
  prefs.putBool("slide", slideshowEnabled);
  prefs.putUChar("bright", oledBrightness);
}

void loadConfig() {
  frameCount = prefs.getUChar("frames", 0);
  slideshowInterval = prefs.getUInt("interval", 1000);
  slideshowEnabled = prefs.getBool("slide", false);
  oledBrightness = prefs.getUChar("bright", 255);

  if (frameCount > MAX_FRAMES) frameCount = 0;
  if (slideshowInterval < 100) slideshowInterval = 100;
  if (slideshowInterval > 60000) slideshowInterval = 60000;
}

