<script>
const W=72,H=40,FS=360;
let src=null;

const $=id=>document.getElementById(id);
const canvas=$("canvas"),ctx=canvas.getContext("2d");
const animCanvas=$("animPreview"),actx=animCanvas.getContext("2d");

function page(id,b){
 document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));
 document.querySelectorAll(".tab").forEach(x=>x.classList.remove("active"));
 $(id).classList.add("active"); b.classList.add("active");
}

function clearC(c,x){
 x.fillStyle="#000";x.fillRect(0,0,W,H);
}
clearC(canvas,ctx);clearC(animCanvas,actx);

$("file").onchange=e=>{
 const f=e.target.files[0]; if(!f)return;
 loadImage(f).then(i=>{src=i;render();}).catch(()=>status("Не удалось открыть файл"));
};

["mode","zoom","posX","posY","rot","flipX","flipY","thr","dither","invert"].forEach(id=>{
 $(id).addEventListener("input",render);
 $(id).addEventListener("change",render);
});

$("zoom").oninput=()=>{$("zoomV").textContent=$("zoom").value+"%";render()};
$("posX").oninput=()=>{$("posXV").textContent=$("posX").value;render()};
$("posY").oninput=()=>{$("posYV").textContent=$("posY").value;render()};
$("thr").oninput=()=>{$("thrV").textContent=$("thr").value;render()};
$("bright").oninput=()=>{$("brightV").textContent=$("bright").value};
$("maxFrames").oninput=()=>{$("maxFramesV").textContent=$("maxFrames").value};
$("interval").oninput=()=>{$("intervalV").textContent=(+$("interval").value/1000).toFixed(1)+" с"};

function loadImage(file){
 return new Promise((resolve,reject)=>{
  const r=new FileReader();
  r.onload=e=>{
   const i=new Image();
   i.onload=()=>resolve(i); i.onerror=reject; i.src=e.target.result;
  };
  r.onerror=reject;r.readAsDataURL(file);
 });
}

function renderTo(c,x,img){
 if(!img)return;
 const tmp=document.createElement("canvas"),t=tmp.getContext("2d");
 tmp.width=W;tmp.height=H;t.fillStyle="#000";t.fillRect(0,0,W,H);

 const rot=+$("rot").value;
 let iw=img.width,ih=img.height;
 if(rot===90||rot===270){const q=iw;iw=ih;ih=q}

 let s;
 if($("mode").value==="fit")s=Math.min(W/iw,H/ih);
 else if($("mode").value==="crop")s=Math.max(W/iw,H/ih);
 else s=W/iw;

 s*=+$("zoom").value/100;
 let dw=img.width*s,dh=img.height*s;
 let dx=(W-dw)/2 + +$("posX").value;
 let dy=(H-dh)/2 + +$("posY").value;

 t.save();
 t.translate(W/2,H/2);
 t.rotate(rot*Math.PI/180);
 t.scale($("flipX").checked?-1:1,$("flipY").checked?-1:1);
 t.drawImage(img,-dw/2+dx,-dh/2+dy,dw,dh);
 t.restore();

 let d=t.getImageData(0,0,W,H), g=new Float32Array(W*H);
 const th=+$("thr").value,di=$("dither").checked,inv=$("invert").checked;

 for(let p=0;p<W*H;p++){
  const i=p*4;
  g[p]=.299*d.data[i]+.587*d.data[i+1]+.114*d.data[i+2];
 }

 if(di){
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){
   const p=y*W+x,old=g[p],nv=old>=th?255:0,e=old-nv;g[p]=nv;
   if(x+1<W)g[p+1]+=e*7/16;
   if(x&&y+1<H)g[p+W-1]+=e*3/16;
   if(y+1<H)g[p+W]+=e*5/16;
   if(x+1<W&&y+1<H)g[p+W+1]+=e/16;
  }
 } else for(let p=0;p<W*H;p++)g[p]=g[p]>=th?255:0;

 for(let p=0;p<W*H;p++){
  let v=inv?255-g[p]:g[p],i=p*4;
  d.data[i]=d.data[i+1]=d.data[i+2]=v;d.data[i+3]=255;
 }
 x.putImageData(d,0,0);
}

function render(){if(src)renderTo(canvas,ctx,src)}
function bitmap(c,x){
 const d=x.getImageData(0,0,W,H).data,b=new Uint8Array(FS);
 for(let y=0;y<H;y++)for(let xx=0;xx<W;xx++){
  if(d[(y*W+xx)*4]>127)b[y*9+(xx>>3)]|=1<<(xx&7);
 }
 return b;
}

async function uploadFrame(index,b){
 const fd=new FormData();
 fd.append("frame",new Blob([b],{type:"application/octet-stream"}),"frame.bin");
 const r=await fetch("/api/upload?index="+index,{method:"POST",body:fd});
 if(!r.ok)throw new Error();
}

async function sendCurrent(){
 if(!src){status("Выберите изображение");return}
 render();
 status("Загрузка...");
 try{
  await fetch("/api/clearframes",{method:"POST"});
  await uploadFrame(0,bitmap(canvas,ctx));
  await fetch("/api/setframes?count=1",{method:"POST"});
  await fetch("/api/config?slideshow=0",{method:"POST"});
  status("✓ Изображение показано");
  updateStatus();
 }catch(e){status("Ошибка загрузки")}
}

function resetEditor(){
 $("mode").value="fit";$("zoom").value=100;$("posX").value=0;$("posY").value=0;
 $("rot").value=0;$("flipX").checked=false;$("flipY").checked=false;
 $("thr").value=128;$("dither").checked=false;$("invert").checked=false;
 $("zoomV").textContent="100%";$("posXV").textContent="0";$("posYV").textContent="0";$("thrV").textContent="128";
 render();
}

async function decodeGif(file){
 if(typeof ImageDecoder==="undefined")throw new Error("ImageDecoder не поддерживается");
 const dec=new ImageDecoder({data:await file.arrayBuffer(),type:file.type||"image/gif"});
 await dec.tracks.ready;
 const tr=dec.tracks.selectedTrack;
 const n=Math.min(tr.frameCount,+$("maxFrames").value);
 const out=[];
 for(let i=0;i<n;i++){
  const r=await dec.decode({frameIndex:i});
  const vf=r.image;
  const c=document.createElement("canvas");c.width=vf.displayWidth;c.height=vf.displayHeight;
  const q=c.getContext("2d");q.drawImage(vf,0,0);vf.close();
  const im=new Image();im.src=c.toDataURL("image/png");await new Promise((ok,bad)=>{im.onload=ok;im.onerror=bad});
  out.push(im);
 }
 dec.close();
 return out;
}

async function prepareAnimation(){
 const fs=[...$("files").files];
 if(!fs.length){astatus("Выберите GIF или изображения");return}
 const max=+$("maxFrames").value;
 let frames=[];
 try{
  if(fs.length===1 && fs[0].type==="image/gif"){
   frames=await decodeGif(fs[0]);
  }else{
   for(let f of fs.slice(0,max))frames.push(await loadImage(f));
  }
  if(!frames.length)throw new Error();
  await fetch("/api/clearframes",{method:"POST"});
  for(let i=0;i<Math.min(frames.length,max);i++){
   src=frames[i];renderTo(animCanvas,actx,src);
   astatus("Загрузка кадра "+(i+1)+" из "+Math.min(frames.length,max));
   await uploadFrame(i,bitmap(animCanvas,actx));
  }
  const n=Math.min(frames.length,max);
  await fetch("/api/setframes?count="+n,{method:"POST"});
  await fetch("/api/config?interval="+$("interval").value+"&slideshow=0",{method:"POST"});
  astatus("✓ Загружено: "+n+" кадров");
  updateStatus();
 }catch(e){
  astatus("Ошибка. Для GIF нужен современный Chrome/Edge с ImageDecoder.");
 }
}

async function startSlide(){
 await fetch("/api/config?interval="+$("interval").value+"&slideshow=1",{method:"POST"});
 astatus("▶ Анимация запущена");
}
async function stopSlide(){
 await fetch("/api/config?slideshow=0",{method:"POST"});
 astatus("■ Анимация остановлена");
}
async function setBrightness(){
 await fetch("/api/brightness?value="+$("bright").value,{method:"POST"});
 status("Яркость применена");
}
async function clearAll(){
 if(!confirm("Удалить все изображения?"))return;
 await fetch("/api/clearframes",{method:"POST"});
 status("Память очищена");updateStatus();
}
async function deleteFrames(){
 await fetch("/api/clearframes",{method:"POST"});
 astatus("Кадры удалены");updateStatus();
}
function status(s){$("status").textContent=s}
function astatus(s){$("animStatus").textContent=s}

async function updateStatus(){
 try{
  const s=await (await fetch("/api/status")).json();
  $("count").textContent=s.frames;
  $("used").textContent=(s.frames*360/1024).toFixed(1);
 }catch(e){}
}
updateStatus();
</script>
