</html>
)HTML";

// -----------------------------
// Web handlers
// -----------------------------
void handleRoot() {
  server.send_P(200, "text/html; charset=utf-8", INDEX_HTML);
}

void handleUploadData() {
  HTTPUpload& up = server.upload();

  if (up.status == UPLOAD_FILE_START) {
    uploadBytes = 0;
    uploadTarget = server.hasArg("index") ? server.arg("index").toInt() : -1;
    uploadValid = (uploadTarget >= 0 && uploadTarget < MAX_FRAMES);
    memset(frameBuffer, 0, FRAME_SIZE);
  }
  else if (up.status == UPLOAD_FILE_WRITE) {
    if (!uploadValid) return;

    if (uploadBytes + up.currentSize <= FRAME_SIZE) {
      memcpy(frameBuffer + uploadBytes, up.buf, up.currentSize);
      uploadBytes += up.currentSize;
    }
    else {
      uploadValid = false;
    }
  }
  else if (up.status == UPLOAD_FILE_END) {
    if (uploadValid && uploadBytes == FRAME_SIZE) {
      saveFrame((uint8_t)uploadTarget, frameBuffer);
      loadFrame((uint8_t)uploadTarget);
    }
    uploadBytes = 0;
    uploadTarget = -1;
    uploadValid = false;
  }
  else if (up.status == UPLOAD_FILE_ABORTED) {
    uploadBytes = 0;
    uploadTarget = -1;
    uploadValid = false;
  }
}

void handleUploadDone() {
  server.send(200, "text/plain", "OK");
}

void handleSetFrames() {
  int n = server.hasArg("count") ? server.arg("count").toInt() : 0;
  n = constrain(n, 0, MAX_FRAMES);

  frameCount = (uint8_t)n;
  currentFrame = 0;
  slideshowEnabled = false;
  saveConfig();

  if (frameCount) loadFrame(0);
  else clearDisplayOnly();

  server.send(200, "text/plain", "OK");
}

void handleClearFrames() {
  clearAllFrames();
  server.send(200, "text/plain", "OK");
}

void handleConfig() {
  if (server.hasArg("interval")) {
    slideshowInterval = server.arg("interval").toInt();
    slideshowInterval = constrain(slideshowInterval, 100UL, 60000UL);
  }

  if (server.hasArg("slideshow")) {
    slideshowEnabled = server.arg("slideshow").toInt() == 1;
    lastFrameTime = millis();
  }

  saveConfig();
  server.send(200, "text/plain", "OK");
}

void handleBrightness() {
  if (server.hasArg("value")) {
    int v = constrain(server.arg("value").toInt(), 0, 255);
    oledBrightness = (uint8_t)v;
    oled.setContrast(oledBrightness);
    saveConfig();
  }

  server.send(200, "text/plain", "OK");
}

void handleStatus() {
  String j;
  j.reserve(180);
  j += "{\"frames\":";
  j += frameCount;
  j += ",\"current\":";
  j += currentFrame;
  j += ",\"interval\":";
  j += slideshowInterval;
  j += ",\"slideshow\":";
  j += slideshowEnabled ? "true" : "false";
  j += ",\"brightness\":";
  j += oledBrightness;
  j += ",\"free\":";
  j += (LittleFS.totalBytes() - LittleFS.usedBytes());
  j += "}";

  server.send(200, "application/json", j);
}

// -----------------------------
// Setup
// -----------------------------
void setup() {
  Wire.begin(OLED_SDA, OLED_SCL);

  oled.begin();
  oled.setContrast(255);
  oled.clearBuffer();
  oled.sendBuffer();

  if (!LittleFS.begin(true)) {
    clearDisplayOnly();
    return;
  }

  prefs.begin("oled21", false);
  loadConfig();
  oled.setContrast(oledBrightness);

  if (frameCount > 0) {
    if (!loadFrame(0)) {
      frameCount = 0;
      saveConfig();
      clearDisplayOnly();
    }
  }

  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID, AP_PASSWORD);

  server.on("/", HTTP_GET, handleRoot);

  // Browser sends a multipart/form-data request.
  // handleUploadData receives the binary frame.
  server.on(
    "/api/upload",
    HTTP_POST,
    handleUploadDone,
    handleUploadData
  );

  server.on("/api/setframes", HTTP_POST, handleSetFrames);
  server.on("/api/clearframes", HTTP_POST, handleClearFrames);
  server.on("/api/config", HTTP_POST, handleConfig);
  server.on("/api/brightness", HTTP_POST, handleBrightness);
  server.on("/api/status", HTTP_GET, handleStatus);

  server.begin();
}

// -----------------------------
// Loop
// -----------------------------
void loop() {
  server.handleClient();

  if (slideshowEnabled && frameCount > 1) {
    uint32_t now = millis();

    if (now - lastFrameTime >= slideshowInterval) {
      lastFrameTime = now;

      uint8_t next = currentFrame + 1;
      if (next >= frameCount) next = 0;

      loadFrame(next);
    }
  }
}
